_DM_OWNER = 'OWNER: DEVRAN E. / BEYİP_'
_DM_OWNER_SEAL = '331d0a8f198cf003c1c0fb9fc09d279aa3d4d2256e016a31bc86d00a89c8b921'
_DM_SOURCE_HASH = 'd84befaa927727654cf6cf97adb9bb4dbde0153a13e7c771f40623a1d3e548b0'
_DM_SIGNATURE = ''
_DM_PUBLIC_N = int('', 16)
_DM_SOURCE_PATH = _dm_Path(__file__).resolve()
_DM_REQUIRED_HEADER = (
    '# ==================================================\n'
    '# DocMind CLI AI Agent\n'
    '# Author / Creator: DEVRAN E. / BEYİP_\n'
    '# Social / Handle: BEYİP_\n'
    '# License: MIT License\n'
    '# ==================================================\n'
).encode('utf-8')
def _dm_attestation_failure(reason=''):
    try:
        msg = (
            '\x1b[1;31m[KORUMA KİLİDİ] DocMind imza / sahip doğrulaması başarısız! '
            '(OWNER: DEVRAN E. / BEYİP_ imzası veya kaynak bütünlüğü silinmiş/değiştirilmiş; kod çalıştırılamaz.)\x1b[0m\n'
        )
        _dm_sys.stderr.write(msg)
        _dm_sys.stderr.flush()
    finally:
        raise SystemExit(90)
# The owner row is the signature of this program: delete it, blank it, duplicate it or
# move it and DocMind refuses to start anywhere (exit 90). Checked on every launch:
#   1. the owner/MIT header must be the first bytes of the file,
#   2. _DM_OWNER must exist exactly once, at column 0, and match its seal,
#   3. the printed owner banner must still be present in the source.
_DM_BANNER = "print(('\\x1b[1;31m' + _DM_OWNER + '\\x1b[0m') if _dm_red_ok else _DM_OWNER, flush=True)"


def _dm_owner_gate():
    try:
        if not isinstance(_DM_OWNER, str) or 'DEVRAN E.' not in _DM_OWNER or 'BEYİP_' not in _DM_OWNER:
            raise ValueError('Owner identity missing')
        if _DM_OWNER.strip() != _DM_OWNER or not _DM_OWNER.startswith('OWNER: '):
            raise ValueError('Owner row damaged')
        calc_seal = _dm_hashlib.sha256(_DM_OWNER.encode('utf-8')).hexdigest()
        if not _dm_hmac.compare_digest(calc_seal, _DM_OWNER_SEAL):
            raise ValueError('Owner seal mismatch')
        raw = _DM_SOURCE_PATH.read_bytes()
        if not raw.startswith(_DM_REQUIRED_HEADER):
            raise ValueError('Required owner header altered')
        if bool(_dm_os.environ.get('DOCMIND_NO_OWNER_CHECK')):
            raise ValueError('Owner check disabled by environment')
        owner_row = ("_DM_OWNER = '" + _DM_OWNER + "'").encode('utf-8')
        if raw.count(owner_row) != 1:
            raise ValueError('Owner constant altered, duplicated or moved in source')
        if not _dm_re.search(rb"(?m)^_DM_OWNER = 'OWNER: DEVRAN E\. / BEY", raw):
            raise ValueError('Owner row must stay at column 0')
        if _DM_BANNER.encode('utf-8') not in raw:
            raise ValueError('Owner banner removed from source')
    except Exception:
        _dm_attestation_failure('owner')
def _dm_attestation_data():
    data = _DM_SOURCE_PATH.read_bytes()
    hash_matches = list(_dm_re.finditer(br"(?m)^_DM_SOURCE_HASH = '([0-9a-f]{64})'$", data))
    sig_matches = list(_dm_re.finditer(br"(?m)^_DM_SIGNATURE = '([0-9a-f]{768})'$", data))
    if len(hash_matches) != 1 or len(sig_matches) != 1 or not data.startswith(_DM_REQUIRED_HEADER):
        raise ValueError('Invalid attestation metadata')
    h, s = hash_matches[0], sig_matches[0]
    canonical = bytearray(data)
    canonical[h.start(1):h.end(1)] = b'0' * 64
    canonical[s.start(1):s.end(1)] = b'0' * 768
    return bytes(canonical), h.group(1).decode('ascii'), bytes.fromhex(s.group(1).decode('ascii'))
def _dm_digest_gate():
    try:
        canonical, expected, _signature = _dm_attestation_data()
        digest = _dm_hashlib.sha256(canonical).hexdigest()
        if not _dm_hmac.compare_digest(digest, expected):
            raise ValueError('Digest mismatch')
    except Exception:
        _dm_attestation_failure('digest')
def _dm_signature_gate():
    try:
        canonical, _expected, signature = _dm_attestation_data()
        key_size = (_DM_PUBLIC_N.bit_length() + 7) // 8
        if len(signature) != key_size or int.from_bytes(signature, 'big') >= _DM_PUBLIC_N:
            raise ValueError('Invalid signature size')
        actual = pow(int.from_bytes(signature, 'big'), 65537, _DM_PUBLIC_N).to_bytes(key_size, 'big')
        digest_info = bytes.fromhex('3031300d060960864801650304020105000420') + _dm_hashlib.sha256(canonical).digest()
        pad_len = key_size - len(digest_info) - 3
        if pad_len < 8:
            raise ValueError('Invalid public key')
        expected = bytes.fromhex('0001') + bytes.fromhex('ff') * pad_len + bytes.fromhex('00') + digest_info
        if not _dm_hmac.compare_digest(actual, expected):
            raise ValueError('Signature mismatch')
    except Exception:
        _dm_attestation_failure('signature')
if _dm_os.name == 'nt':
    try:
        import ctypes as _dm_ctypes
        _dm_k32 = _dm_ctypes.windll.kernel32
        for _dm_hid in (-11, -12):
            _dm_h = _dm_k32.GetStdHandle(_dm_hid)
            if _dm_h and _dm_h != -1:
                _dm_m = _dm_ctypes.c_ulong()
                if _dm_k32.GetConsoleMode(_dm_h, _dm_ctypes.byref(_dm_m)):
                    _dm_k32.SetConsoleMode(_dm_h, _dm_m.value | 0x0004)
    except Exception:
        pass
for _dm_stream in (_dm_sys.stdout, _dm_sys.stderr):
    try:
        if hasattr(_dm_stream, 'reconfigure'):
            _dm_stream.reconfigure(encoding='utf-8', errors='replace')
    except Exception:
        pass

# ==================================================
# MOBILE LAYER (Termux / Android / small terminals) -- v1.3
# ==================================================
def _dm_detect_mobile():
    """True on Termux / Android / iOS shells and other tiny terminals."""
    try:
        if _dm_os.environ.get('TERMUX_VERSION') or _dm_os.environ.get('TERMUX_APP_PID'):
            return True
        if 'ANDROID_ROOT' in _dm_os.environ or 'ANDROID_DATA' in _dm_os.environ:
            return True
        if _dm_sys.prefix and any(_dm_sys.prefix.startswith(p) for p in
                                  ('/data/data/com.termux', '/system/bin', '/data/local/tmp')):
            return True
        if _dm_sys.platform.startswith(('android', 'ios')):
            return True
        if _dm_os.environ.get('DOCMIND_MOBILE', '').lower() in ('1', 'true', 'yes', 'on'):
            return True
        try:
            cols = _dm_os.get_terminal_size().columns
        except Exception:
            cols = int(_dm_os.environ.get('COLUMNS', '0') or 0)
        return bool(0 < cols and cols < 46)
    except Exception:
        return False


def _dm_storage_root():
    """Shared storage root on a phone/tablet (Termux storage, /sdcard), else ''."""
    try:
        home = _dm_Path.home()
        for path in (home / 'storage' / 'shared', home / 'storage' / 'downloads',
                     home / 'storage' / 'dcim', _dm_Path('/sdcard'),
                     _dm_Path('/storage/emulated/0')):
            if path.exists():
                return str(path)
    except Exception:
        pass
    return ''


_DM_MOBILE = _dm_detect_mobile()
if _dm_os.environ.get('DOCMIND_MOBILE', '').lower() in ('0', 'false', 'no', 'off'):
    _DM_MOBILE = False
if _dm_os.environ.get('DOCMIND_DESKTOP', '').lower() in ('1', 'true', 'yes', 'on'):
    _DM_MOBILE = False


def _dm_phone_device():
    """Strict hardware answer for /mobil: a phone/tablet, never a narrow desktop.

    ``_dm_detect_mobile`` also treats a tiny terminal as "mobile" (useful for the
    width defaults).  The /mobil switch must not: a desktop user who happens to
    have a narrow window still gets "this is a computer".
    """
    try:
        flag = _dm_os.environ.get('DOCMIND_MOBILE', '').lower()
        if flag in ('1', 'true', 'yes', 'on'):
            return True
        if _dm_os.environ.get('DOCMIND_DESKTOP', '').lower() in ('1', 'true', 'yes', 'on'):
            return False
        if _dm_os.environ.get('TERMUX_VERSION') or _dm_os.environ.get('TERMUX_APP_PID'):
            return True
        if 'ANDROID_ROOT' in _dm_os.environ or 'ANDROID_DATA' in _dm_os.environ:
            return True
        if _dm_sys.prefix and any(_dm_sys.prefix.startswith(p) for p in
                                  ('/data/data/com.termux', '/data/local/tmp')):
            return True
        if _dm_sys.platform.startswith(('android', 'ios')):
            return True
    except Exception:
        return False
    return False


_DM_PHONE_DEVICE = _dm_phone_device()
_DM_MOBILE_MODE = False
_DM_ASCII_AUTOSET = False


_DM_WIDTH_AUTOSET = False


def _dm_refresh_glyphs() -> None:
    """Recompute the ASCII/Unicode glyph choice after a mode switch."""
    san_mod = _dm_sys.modules.get('docmind.core.sanitize')
    if san_mod is None:
        return
    try:
        force = str(_dm_os.environ.get('DOCMIND_ASCII', '') or
                    _dm_os.environ.get('DOCMIND_GLYPHS', '')).strip().lower()
        plain = bool(force and force not in ('0', 'false', 'no', 'off', 'unicode', 'utf8', 'utf-8'))
        if plain and _DM_ASCII_AUTOSET and not _DM_MOBILE_MODE:
            plain = False
        san_mod.ASCII_GLYPHS = bool(plain or _DM_MOBILE_MODE)
    except Exception:
        pass


def _dm_set_mobile_mode(enabled) -> None:
    """Switch the mobile layout on/off right now (footer, prompt, glyphs, rules)."""
    global _DM_MOBILE, _DM_MOBILE_MODE, _DM_ASCII_AUTOSET, _DM_WIDTH_AUTOSET
    _DM_MOBILE_MODE = bool(enabled) and bool(_DM_PHONE_DEVICE)
    _DM_MOBILE = _DM_MOBILE_MODE
    _dm_os.environ['DOCMIND_MOBILE_MODE'] = '1' if _DM_MOBILE_MODE else '0'
    if _DM_MOBILE_MODE:
        if not str(_dm_os.environ.get('DOCMIND_ASCII', '') or '').strip():
            _dm_os.environ['DOCMIND_ASCII'] = '1'
            _DM_ASCII_AUTOSET = True
        if not _dm_os.environ.get('TERM_WIDTH'):
            _dm_os.environ['TERM_WIDTH'] = '44'
            _DM_WIDTH_AUTOSET = True
    elif _DM_ASCII_AUTOSET:
        # We forced ASCII when the mode came on: put the terminal back to normal.
        if _DM_WIDTH_AUTOSET:
            _dm_os.environ.pop("TERM_WIDTH", None)
        _dm_os.environ.pop('DOCMIND_ASCII', None)
        _DM_ASCII_AUTOSET = False
    _dm_refresh_glyphs()


_DM_STORAGE_ROOT = _dm_storage_root()

if _dm_os.name == 'posix' and hasattr(_dm_sys.stdout, 'reconfigure'):
    try:
        _dm_sys.stdout.reconfigure(errors='replace', line_buffering=True)
        _dm_sys.stderr.reconfigure(errors='replace', line_buffering=True)
    except Exception:
        pass
if _DM_MOBILE:
    _dm_os.environ.setdefault('NO_COLOR', '0')
    _dm_os.environ.setdefault('PYTHONUTF8', '1')
    _dm_os.environ.setdefault('PYTHONIOENCODING', 'utf-8:replace')
    if not _dm_os.environ.get('TERM_WIDTH'):
        _dm_os.environ['TERM_WIDTH'] = '44'
        _DM_WIDTH_AUTOSET = True

_dm_owner_gate()
_dm_digest_gate()
_dm_signature_gate()
if __name__ == '__main__':
    _dm_red_ok = not _dm_os.environ.get('NO_COLOR') and _dm_os.environ.get('TERM', '').lower() != 'dumb'
    print(('\x1b[1;31m' + _DM_OWNER + '\x1b[0m') if _dm_red_ok else _DM_OWNER, flush=True)
def _dm_package(name):
    mod = _dm_sys.modules.get(name)
    if mod is None:
        mod = _dm_types.ModuleType(name)
        mod.__package__ = name
        mod.__path__ = []
        _dm_sys.modules[name] = mod
        if "." in name:
            parent, _, leaf = name.rpartition(".")
            setattr(_dm_sys.modules[parent], leaf, mod)
    return mod
def _dm_install(name, factory, is_package=False):
    parent, _, leaf = name.rpartition(".")
    if is_package:
        mod = _dm_package(name)
    else:
        mod = _dm_types.ModuleType(name)
        mod.__package__ = parent
        _dm_sys.modules[name] = mod
        setattr(_dm_sys.modules[parent], leaf, mod)
    mod.__dict__.update(factory())
    return mod
for _package_name in ("docmind", "docmind.i18n", "docmind.core", "docmind.tools", "docmind.ui"):
    _dm_package(_package_name)

