 PROVIDER_MAP: Dict[str, ProviderSpec] = {p.id: p for p in PROVIDERS}
 def get_provider_spec(provider_id: str) -> ProviderSpec:
   return PROVIDER_MAP.get(provider_id, PROVIDERS[0])
 def _restrict_windows_acl(target) -> None:
   """Windows has no chmod bits; restrict the config file to the current user."""
   import subprocess
   try:
     if not target.is_file():
       return
     user = os.environ.get("USERNAME", "")
     if not user:
       return
     subprocess.run(
       ["icacls", str(target), "/inheritance:r", "/grant:r", f"{user}:F"],
       stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
       timeout=6, check=False,
     )
   except Exception:
     pass
 def clean_api_key(raw: str) -> str:
   """Strip accidental quotes, whitespace, or 'Bearer ' prefixes from pasted keys."""
   if not raw:
     return ""
   cleaned = str(raw).strip()
   for _ in range(4):
     value = cleaned.strip().strip("\"'").strip()
     if len(value) > 6 and value[:6].lower() == "bearer" and value[6].isspace():
       value = value[6:].strip()
     if value == cleaned:
       break
     cleaned = value
   return cleaned
 @dataclass
 class DocMindConfig:
   language: str = "tr"
   provider: str = "anthropic"
   model: str = "claude-sonnet-5-5"
   api_keys: Dict[str, str] = field(default_factory=dict)
   base_urls: Dict[str, str] = field(default_factory=dict)
   permission_mode: str = "smart"
   max_steps_per_turn: int = 65
   # Aggressive Engine: extra verification + project-memory layers (on by default).
   aggressive_mode: bool = True
   # v1.3 Squad Engine: ask | auto | off, plus the agent cap.
   squad_mode: str = "ask"
   squad_max_agents: int = 6
   # agents run at the same time; file owners are separated into waves.
   squad_parallel: bool = True
   # v1.3 automatic web research: search without the user typing /search.
   auto_search: bool = True
   # v1.3 terminal fidelity on phones / Termux.
   mobile_mode: bool = False
   glyph_mode: str = "auto"
   max_output_tokens: int = 12288
   reasoning_effort: str = "high"
   token_save: bool = True
   temperature: float = 0.2
   token_warning_limit: int = 0
   price_overrides: Dict[str, List[float]] = field(default_factory=dict)
   context_overrides: Dict[str, int] = field(default_factory=dict)
