def _dm_module_09():
 """Bounded, read-only project discovery and multi-language non-executing syntax checks."""
 import ast
 import json
 import os
 import shutil
 import subprocess
 import sys
 import xml.etree.ElementTree as ET
 from collections import Counter
 from pathlib import Path
 from typing import Any, Dict, List, Tuple
 from docmind.core.safety import sensitive_path
 from docmind.tools.filesystem import resolve_user_path
 _SKIP_DIRS = {
   ".git", ".hg", ".svn", ".cache", ".venv", "venv", "__pycache__",
   "node_modules", "vendor", "dist", "build", "target", "out", "coverage",
   ".next", ".pytest_cache", ".mypy_cache", ".tox", ".gradle", ".dart_tool",
 }
 _LANGUAGE_EXTENSIONS = {
   ".py": "Python", ".pyi": "Python", ".js": "JavaScript", ".jsx": "JavaScript",
   ".mjs": "JavaScript", ".cjs": "JavaScript", ".ts": "TypeScript", ".tsx": "TypeScript",
   ".go": "Go", ".rs": "Rust", ".c": "C", ".h": "C/C++", ".cc": "C++", ".cpp": "C++",
   ".hpp": "C++", ".java": "Java", ".kt": "Kotlin", ".kts": "Kotlin", ".cs": "C#",
   ".fs": "F#", ".rb": "Ruby", ".php": "PHP", ".swift": "Swift", ".dart": "Dart",
   ".ex": "Elixir", ".exs": "Elixir", ".erl": "Erlang", ".hs": "Haskell", ".lua": "Lua",
   ".sh": "Shell", ".bash": "Shell", ".zsh": "Shell", ".ps1": "PowerShell",
   ".html": "HTML", ".htm": "HTML", ".css": "CSS", ".scss": "SCSS", ".vue": "Vue",
   ".svelte": "Svelte", ".sql": "SQL", ".r": "R", ".jl": "Julia", ".gd": "GDScript",
 }
 _MANIFESTS = {
   "agents.md", "readme.md", "pyproject.toml", "requirements.txt", "setup.py", "setup.cfg",
   "pytest.ini", "tox.ini", "package.json", "package-lock.json", "pnpm-lock.yaml", "yarn.lock",
   "bun.lock", "bun.lockb", "cargo.toml", "cargo.lock", "go.mod", "go.sum", "gemfile",
   "gemfile.lock", "pom.xml", "build.gradle", "build.gradle.kts", "gradlew", "composer.json",
   "mix.exs", "pubspec.yaml", "makefile", "cmakelists.txt", "dockerfile", "docker-compose.yml",
   "compose.yaml", "deno.json", "deno.jsonc", "tsconfig.json", "vite.config.ts", "vite.config.js",
   "pkgbuild",
 }
 def tool_project_overview(args: Dict[str, Any], cwd: Path) -> Tuple[bool, str]:
   """Summarize a bounded project tree; never execute a project command."""
   root = resolve_user_path(str(args.get("path") or "."), cwd)
   if not root.exists() or not root.is_dir():
     return False, f"Project directory not found: {root}"
   depth_limit = max(1, min(5, int(args.get("max_depth", 3) or 3)))
   limit = max(50, min(1800, int(args.get("max_files", 900) or 900)))
   max_directories = max(25, min(900, limit // 2))
   files: List[str] = []
   manifests: List[str] = []
   pkg_paths: List[Path] = []
   languages: Counter = Counter()
   truncated = False
   directories_truncated = False
   directories_seen = 0
   walk_errors: List[str] = []
   def record_error(exc: OSError) -> None:
     if len(walk_errors) < 3:
       walk_errors.append(str(exc))
   for dirpath, dirs, names in os.walk(root, topdown=True, followlinks=False, onerror=record_error):
     directories_seen += 1
     if directories_seen > max_directories:
       directories_truncated = True
       break
     base = Path(dirpath)
     depth = len(base.relative_to(root).parts)
     selected_dirs: List[str] = []
     for name in sorted(dirs, key=str.lower):
       if (
         depth >= depth_limit
         or name.lower() in _SKIP_DIRS
         or name.startswith(".")
         or (base / name).is_symlink()
         or sensitive_path(str(base / name), cwd)
       ):
         continue
       if len(selected_dirs) >= max_directories - directories_seen:
         directories_truncated = True
         break
       selected_dirs.append(name)
     dirs[:] = selected_dirs
     for name in sorted(names, key=str.lower):
       path = base / name
       if name.startswith(".") or path.is_symlink() or sensitive_path(str(path), cwd):
         continue
       rel = str(path.relative_to(root)).replace(os.sep, "/")
       files.append(rel)
       low = name.lower()
       language = _LANGUAGE_EXTENSIONS.get(path.suffix.lower())
       if language:
         languages[language] += 1
       if low in _MANIFESTS or low.endswith((".sln", ".csproj")):
         manifests.append(rel)
       if low == "package.json" and len(pkg_paths) < 8:
         pkg_paths.append(path)
       if len(files) >= limit:
         truncated = True
         break
     if truncated:
       break
   output = [
     f"Project: {root}",
     f"Files scanned: {len(files)}" + (" (bounded; more may exist)" if truncated or directories_truncated else ""),
     f"Directories visited: {min(directories_seen, max_directories)} (maximum {max_directories}; depth {depth_limit})",
     "Languages by file count: " + (", ".join(f"{name}={count}" for name, count in languages.most_common(16)) or "not detected"),
     "Project markers: " + (", ".join(manifests[:35]) if manifests else "none detected"),
   ]
   for package in pkg_paths:
     try:
       with package.open("rb") as stream:
         package_data = stream.read(256 * 1024 + 1)
       if len(package_data) > 256 * 1024:
         continue
       parsed = json.loads(package_data.decode("utf-8-sig"))
       if not isinstance(parsed, dict):
         continue
       scripts = parsed.get("scripts") if isinstance(parsed.get("scripts"), dict) else {}
       dependencies = {}
       for key in ("dependencies", "devDependencies"):
         part = parsed.get(key)
         if isinstance(part, dict):
           dependencies.update(part)
       script_names = [str(k)[:60] for k in scripts.keys() if isinstance(k, str)][:20]
       known = (
         "react", "next", "vue", "svelte", "vite", "express", "fastify",
         "typescript", "jest", "vitest", "playwright", "@angular/core",
       )
       frameworks = [name for name in known if name in dependencies]
       if script_names or frameworks:
         rel = str(package.relative_to(root)).replace(os.sep, "/")
         output.append(
           f"{rel}: script names=" + (", ".join(script_names) or "none")
           + "; recognized dependencies=" + (", ".join(frameworks) or "none")
         )
     except (OSError, ValueError, UnicodeError):
       pass
   output.append("Sample paths: " + (", ".join(files[:45]) if files else "(empty)"))
   if walk_errors:
     output.append(f"Warning: {len(walk_errors)} directory access error(s); listing may be incomplete.")
   return True, "\n".join(output)
 def _line_context_around(data_bytes: bytes, lineno: int) -> str:
   if not lineno or lineno < 1:
     return ""
   lines = data_bytes.decode("utf-8", errors="replace").splitlines()
   if not lines:
     return ""
   start = max(0, lineno - 3)
   end = min(len(lines), lineno + 2)
   out = ["\nCode context around syntax error:"]
   for idx in range(start, end):
     marker = ">>" if (idx + 1) == lineno else "  "
     out.append(f"  {marker} {idx + 1:5d} | {lines[idx]}")
   return "\n".join(out)
# --- Aggressive Engine: project memory, perfection audit, write snapshots ------------------
 AGGRESSIVE_PLAN_FILE = "AGGRESSIVE_PLAN.md"
 AGGRESSIVE_JOURNAL_FILE = "AGGRESSIVE_JOURNAL.md"
 AGGRESSIVE_BACKUP_DIR = ".docmind_backups"
 AGGRESSIVE_WORK_TOOLS = {"write_file", "edit_file", "multi_edit", "delete_path", "move_or_copy",
                          "run_command", "python_eval", "archive_tool"}
 AGGRESSIVE_AUDIT_SKIP_DIRS = {
   ".git", ".hg", ".svn", "node_modules", "__pycache__", ".venv", "venv", "env",
   ".mypy_cache", ".pytest_cache", ".ruff_cache", "dist", "build", "target",
   ".idea", ".vscode", ".tox", "site-packages", AGGRESSIVE_BACKUP_DIR,
 }
 AGGRESSIVE_CODE_EXTS = {
   ".py", ".pyi", ".js", ".mjs", ".cjs", ".ts", ".tsx", ".jsx", ".json",
   ".sh", ".bash", ".zsh", ".toml", ".xml", ".svg", ".html", ".css", ".sql",
 }
 import datetime as _ag_dt
 import re as _ag_re
 import shutil as _ag_shutil
 AGGRESSIVE_MARKER_RE = _ag_re.compile(r"(?i)\b(TODO|FIXME|XXX|HACK|WIP|STUB)\b")
 AGGRESSIVE_ERROR_PATTERNS = (
   (_ag_re.compile(r"except\s*(?:Exception|BaseException)?\s*:\s*(?:pass|\.\.\.)\s*$", _ag_re.M), "silently swallowed exception"),
   (_ag_re.compile(r"\bnot implemented\b|\bNotImplementedError\b", _ag_re.I), "unimplemented stub"),
 )


 def aggressive_directive() -> str:
   """The behaviour contract that makes Aggressive mode actually aggressive."""
   from docmind.config import aggressive_active as _ag_is_on
   from docmind.config import _aggressive_cfg_holder as _ag_holder
   if not _ag_is_on(getattr(_ag_holder, "cfg", None)):
     return ""
   try:
     first_run = not (Path.cwd() / AGGRESSIVE_PLAN_FILE).is_file()
   except Exception:
     first_run = False
   steps = [
     "**1. CLARIFY ONCE, THEN COMMIT.** If (and only if) a requirement is genuinely ambiguous, ask one compact "
     "`ask_user` question with concrete options, then start. Never ask what you can answer yourself, never re-ask "
     "something already in the conversation, and never end a task with open questions you could have resolved by "
     "reading the code or the internet.",
     "**2. PLAN BEFORE TOUCHING FILES.** Derive the full plan (files, edits, order, risks, verification) before "
     "the first write. For multi-step work keep it in AGGRESSIVE_PLAN.md so it survives context trimming, and keep "
     "it updated as you go.",
     "**3. READ THE CODE, DO NOT GUESS.** Never assume a function, class, config key or import exists: open the "
     "file with `read_file` / `grep_search` first. If a library API or version detail is not 100% certain, verify "
     "it with `web_search` before writing code against it.",
     "**4. NEVER SHIP UNVERIFIED WORK.** Every written or edited code file passes `check_syntax` and, where it can "
     "run, a real execution test (`run_command` / `python_eval`). Every failure is fixed before you report back; "
     "if something cannot be tested, say exactly what is untested and why.",
     "**5. HUNT BUGS TO THE ROOT.** Reproduce, read the real traceback, fix the cause rather than the symptom, "
     "then re-run the exact failing case and confirm it passes. No 'should work' answers, no leftover debug "
     "prints, no dead code, no silent `except: pass`.",
     "**6. PROJECT HYGIENE.** Keep the folder coherent: no duplicate files, no half-written modules, no orphan "
     "imports, no TODOs. Remaining work goes into AGGRESSIVE_JOURNAL.md instead of comments.",
     "**7. PROTECT THE USER'S DATA.** Never delete or overwrite user files or data without an explicit "
     "instruction; prefer additive edits. The previous revision of anything you rewrite is already kept in "
     ".docmind_backups/.",
     "**8. CLOSE PROPERLY.** End every turn with: what changed (paths), what you verified (and how), what is left "
     "(if anything, with the next concrete step). Add one short paragraph about your decisions to "
     "AGGRESSIVE_JOURNAL.md.",
   ]
   head = (
     "\n\n## AGGRESSIVE ENGINE (ACTIVE - maximum quality contract)\n"
     "The user selected the Aggressive level. Aggressive means *zero-defect delivery*, not louder answers: you are "
     "the senior engineer who owns this project. Token saving is off, so use whatever context and steps the job "
     "needs; these rules override every 'keep it short' instinct.\n"
   )
   tail = (
     "\n**Extra tools in this mode:** `aggressive_audit` (perfection audit of the working folder: syntax, "
     "TODO/FIXME markers, error patterns, project memory) and `.docmind_backups/` (previous revision of every "
     "file you rewrote).\n"
   )
   if first_run:
     tail += (
       "**First Aggressive run in this folder:** create AGGRESSIVE_PLAN.md with the plan and assumptions, execute "
       "it, then record the outcome in AGGRESSIVE_JOURNAL.md.\n"
     )
   return head + "\n".join("- " + s for s in steps) + "\n" + tail


 def aggressive_audit_folder(cwd: Path, max_files: int = 600, touched: Optional[Set[str]] = None,
                            with_patterns: bool = True) -> Tuple[bool, str, int]:
   """Scan code files in the working folder (pruned walk, bounded).

     Returns (clean, report, scanned). Findings are tagged so the caller can tell
     blocking problems (syntax errors, anything inside a file the agent just wrote)
     from advisory ones (pre-existing TODOs in a legacy folder).
     """
   findings: List[str] = []
   blocking: List[str] = []
   scanned = 0
   touched = {str(t).replace(os.sep, "/") for t in (touched or set())}
   suffix_check = {".py", ".pyi", ".js", ".mjs", ".cjs", ".sh", ".bash", ".json", ".toml", ".xml"}
   stopped = False
   try:
     for dirpath, dirnames, filenames in os.walk(cwd, onerror=lambda _e: None):
       dirnames[:] = sorted(d for d in dirnames if d not in AGGRESSIVE_AUDIT_SKIP_DIRS and not d.startswith(".docmind_backups"))
       for name in sorted(filenames):
         if scanned >= max_files:
           stopped = True
           break
         path = Path(dirpath) / name
         if path.suffix.lower() not in AGGRESSIVE_CODE_EXTS:
           continue
         try:
           if path.stat().st_size > 2 * 1024 * 1024:
             continue
           from docmind.tools.filesystem import read_text_resilient as _ag_read_text
           text, _ = _ag_read_text(path)
         except Exception:
           continue
         scanned += 1
         try:
           rel = str(path.relative_to(cwd)).replace(os.sep, "/")
         except Exception:
           rel = str(path).replace(os.sep, "/")
         is_touched = rel in touched or name in touched
         markers = []
         for line_no, line in enumerate(text.splitlines(), 1):
           found = AGGRESSIVE_MARKER_RE.search(line)
           if found:
             markers.append(f"{found.group(1).upper()}@{line_no}")
             if len(markers) >= 3:
               break
         if markers:
           item = f"{rel}: unfinished markers {', '.join(markers)}"
           findings.append(item)
           if is_touched:
             blocking.append(item)
         if path.suffix.lower() in suffix_check:
           ok, detail = tool_check_syntax({"path": str(path)}, cwd)
           skippable = ("No built-in syntax parser", "Node.js not installed", "No POSIX shell parser")
           # unreadable/binary payloads and absurdly long single-line files are advisory only
           advisory_only = ("null bytes", "exceeds 4 MiB", "not a regular file")
           if not ok and not any(tag in detail for tag in skippable):
             first = detail.splitlines()[0] if detail else "syntax error"
             item = f"{rel}: SYNTAX -> {first}"
             findings.append(item)
             if not any(tag in detail for tag in advisory_only):
               blocking.append(item)        # a genuine syntax error always blocks
             continue
         if with_patterns and path.suffix.lower() == ".py":
           for pattern, label in AGGRESSIVE_ERROR_PATTERNS:
             if pattern.search(text):
               item = f"{rel}: {label}"
               findings.append(item)
               if is_touched:
                 blocking.append(item)
               break
       if stopped:
         break
   except Exception as exc:
     return False, f"Audit could not read {cwd}: {exc}", scanned
   lines = [f"Scanned {scanned} code file(s) in {cwd}."]
   if findings:
     lines.append(f"Found {len(findings)} issue(s) ({len(blocking)} blocking):")
     lines.extend(" - " + item for item in findings[:40])
     if len(findings) > 40:
       lines.append(f" ... and {len(findings) - 40} more")
   else:
     lines.append("No syntax errors, unfinished markers or suspicious error patterns found.")
   if stopped:
     lines.append(f"(stopped after {max_files} files)")
   lines.append(
     "Project memory: plan=" + ("present" if (cwd / AGGRESSIVE_PLAN_FILE).is_file() else "missing")
     + ", journal=" + ("present" if (cwd / AGGRESSIVE_JOURNAL_FILE).is_file() else "missing")
     + ", backups=" + ("present" if (cwd / AGGRESSIVE_BACKUP_DIR).is_dir() else "none")
   )
   result = "\n".join(lines)
   if blocking:
     result += "\nBLOCKING:\n" + "\n".join(" - " + item for item in blocking[:24])
   return (len(blocking) == 0), result, scanned


 def tool_aggressive_audit(args: Dict[str, Any], cwd: Path) -> Tuple[bool, str]:
   """Tool entry point: audit the working folder (never executes project code)."""
   raw = str(args.get("path") or "").strip()
   folder = resolve_user_path(raw, cwd) if raw else cwd
   if not folder.is_dir():
     return False, f"Error: not a directory: {folder}"
   try:
     limit = int(args.get("max_files") or 600)
   except (TypeError, ValueError):
     limit = 600
   ok, detail, _scanned = aggressive_audit_folder(folder, max(20, min(2000, limit)))
   return ok, detail


 def aggressive_snapshot(path: Path, cwd: Path) -> Optional[str]:
   """Keep the previous revision of a file before the agent rewrites it."""
   try:
     if not path.is_file() or path.stat().st_size > 4 * 1024 * 1024:
       return None
     root = cwd if cwd.is_dir() else path.parent
     try:
       rel = path.resolve().relative_to(root.resolve())
     except Exception:
       rel = Path(path.name)
     dest = root / AGGRESSIVE_BACKUP_DIR / rel
     dest.parent.mkdir(parents=True, exist_ok=True)
     stamp = _ag_dt.datetime.now().strftime("%Y%m%d-%H%M%S")
     dest = dest.with_name(f"{dest.name}.{stamp}{dest.suffix}.bak")
     _ag_shutil.copy2(path, dest)
     # keep only the newest 20 revisions per file so a long session cannot bloat the folder
     try:
       pattern = f"{dest.name.rsplit('.', 2)[0]}.*.bak"
       old = sorted(dest.parent.glob(pattern))
       for stale in old[:-20]:
         stale.unlink(missing_ok=True)
     except Exception:
       pass
     return str(dest)
   except Exception:
     return None


 def tool_check_syntax(args: Dict[str, Any], cwd: Path) -> Tuple[bool, str]:
   """Validate Python, JSON, TOML, XML/SVG, Shell (.sh), or JS (.js/.mjs) syntax without executing user logic."""
   raw_path = str(args.get("path", "")).strip()
   if not raw_path:
     return False, "Error: path is required."
   path = resolve_user_path(raw_path, cwd)
   if not path.is_file():
     return False, f"File not found or not a regular file: {path}"
   size = path.stat().st_size
   if size > 4 * 1024 * 1024:
     return False, f"Syntax check skipped: file exceeds 4 MiB: {path}"
   language = str(args.get("language") or "").strip().lower()
   if not language:
     language = {
       ".py": "python", ".pyi": "python",
       ".json": "json", ".ipynb": "json",
       ".toml": "toml",
       ".xml": "xml", ".svg": "xml", ".plist": "xml", ".csproj": "xml",
       ".sh": "shell", ".bash": "shell",
       ".js": "javascript", ".mjs": "javascript", ".cjs": "javascript",
     }.get(path.suffix.lower(), "")
   data = path.read_bytes()
   try:
     if language in ("python", "py"):
       ast.parse(data, filename=str(path))
       detail = f"Python {sys.version_info.major}.{sys.version_info.minor} AST syntax valid."
     elif language == "json":
       def reject_constant(value: str):
         raise ValueError("Non-standard JSON constant: " + value)
       json.loads(data.decode("utf-8-sig"), parse_constant=reject_constant)
       detail = "Strict JSON syntax valid."
     elif language == "toml":
       try:
         import tomllib
         tomllib.loads(data.decode("utf-8-sig"))
         detail = "TOML syntax valid."
       except ImportError:
         return False, "TOML parsing requires Python 3.11+."
     elif language == "xml":
       ET.fromstring(data.decode("utf-8-sig"))
       detail = "XML structure well-formed."
     elif language == "shell":
       bash_bin = shutil.which("bash") or shutil.which("sh")
       if not bash_bin:
         return True, f"No POSIX shell parser installed to check {path.name}; skipped."
       pr = subprocess.run([bash_bin, "-n", str(path)], capture_output=True, text=True, timeout=8, stdin=subprocess.DEVNULL)
       if pr.returncode != 0:
         err_txt = (pr.stderr or pr.stdout).strip()
         return False, f"Shell syntax check FAILED for {path}:\n{err_txt}\n[SELF-RECOVERY] Fix the shell syntax error with edit_file or undo_file_change."
       detail = f"Shell syntax checked cleanly with '{Path(bash_bin).name} -n' (not executed)."
     elif language == "javascript":
       node_bin = shutil.which("node")
       if not node_bin:
         return True, f"Node.js not installed to syntax-check {path.name}; skipped."
       pr = subprocess.run([node_bin, "--check", str(path)], capture_output=True, text=True, timeout=8, stdin=subprocess.DEVNULL)
       if pr.returncode != 0:
         err_txt = (pr.stderr or pr.stdout).strip()
         return False, f"JavaScript syntax check FAILED for {path}:\n{err_txt}\n[SELF-RECOVERY] Fix the syntax error with edit_file or undo_file_change."
       detail = "JavaScript syntax checked cleanly with 'node --check' (not executed)."
     else:
       return False, f"No built-in syntax parser for '{path.suffix}'; use language-appropriate tooling."
   except (SyntaxError, UnicodeError, ValueError, ET.ParseError) as exc:
     lineno = getattr(exc, "lineno", 0) or (exc.position[0] if isinstance(exc, ET.ParseError) and hasattr(exc, "position") else 0)
     if isinstance(exc, SyntaxError):
       detail = f"{exc.msg} (line {exc.lineno or '?'}, column {exc.offset or '?'})"
     elif isinstance(exc, json.JSONDecodeError):
       detail = f"{exc.msg} (line {exc.lineno}, column {exc.colno})"
     else:
       detail = str(exc)[:300]
     ctx = _line_context_around(data, int(lineno or 0))
     return (
       False,
       f"Syntax check FAILED for {path}: {detail}.{ctx}\n"
       "[SELF-RECOVERY] Go back and fix the broken lines using edit_file, or revert via undo_file_change.",
     )
   return True, f"Syntax check passed for {path}. {detail}"
 return locals()
_dm_install('docmind.tools.project', _dm_module_09, False)

