def _dm_module_18():
 """Dependency-free terminal animations, Windows/Linux ANSI color support, and pinned footer.
 No graphical window, no Python package installation, and no shell interpolation.
 """
 import collections
 import ctypes
 import os
 import re
 import shutil
 import sys
 import threading
 import time
 import unicodedata
 from contextlib import contextmanager
 from typing import Callable, Deque, Optional, Tuple
 def enable_windows_ansi() -> bool:
   """Enable Virtual Terminal ANSI escape sequences on Windows 10/11 CMD & PowerShell."""
   if os.name != "nt":
     return True
   try:
     kernel32 = ctypes.windll.kernel32
     ok_any = False
     for std_id in (-11, -12):
       handle = kernel32.GetStdHandle(std_id)
       if handle and handle != -1:
         mode = ctypes.c_ulong()
         if kernel32.GetConsoleMode(handle, ctypes.byref(mode)):
           if kernel32.SetConsoleMode(handle, mode.value | 0x0004):
             ok_any = True
     return ok_any or bool(os.environ.get("WT_SESSION") or os.environ.get("ANSICON") or os.environ.get("TERM_PROGRAM"))
   except Exception:
     return bool(os.environ.get("WT_SESSION") or os.environ.get("TERM_PROGRAM"))
 def _terminal_width(text: str, limit: int) -> str:
   used = 0
   out = []
   for ch in text:
     width = 0 if unicodedata.combining(ch) else (2 if unicodedata.east_asian_width(ch) in "WF" else 1)
     if used + width > limit:
       break
     out.append(ch)
     used += width
   return "".join(out)
 def _char_width(ch: str) -> int:
   if unicodedata.combining(ch):
     return 0
   return 2 if unicodedata.east_asian_width(ch) in "WF" else 1
 def _display_width(text: str) -> int:
   """Visible terminal columns (emoji and CJK count as two, ANSI codes as zero)."""
   raw = str(text)
   total = 0
   i, n = 0, len(raw)
   while i < n:
     ch = raw[i]
     if ch == chr(27):
       j = i + 1
       if j < n and raw[j] == "[":
         j += 1
         while j < n and not ("@" <= raw[j] <= "~"):
           j += 1
         j += 1
       i = j
       continue
     total += _char_width(ch)
     i += 1
   return total
 def _sanitize_stream_chunk(chunk: Any) -> str:
   """Make model output safe to write straight to a terminal.

   Keeps tabs, newlines and SGR colour codes; a bare carriage return becomes a
   newline (that is what made a half printed line repaint itself on phones) and
   every other control byte is dropped.
   """
   raw = str(chunk)
   raw = raw.replace("\r\n", "\n").replace("\r", "\n")
   out = []
   i = 0
   n = len(raw)
   esc = chr(27)
   while i < n:
     ch = raw[i]
     if ch == "\n" or ch == "\t":
       out.append(ch)
       i += 1
       continue
     if ch == esc:
       # A complete ``ESC [ ... m`` sequence is a colour change DocMind can keep;
       # a lone ESC or an unterminated half sequence is dropped.
       j = i + 1
       if j < n and raw[j] == "[":
         j += 1
         while j < n and (raw[j].isdigit() or raw[j] == ";"):
           j += 1
         if j < n and raw[j] == "m":
           out.append(raw[i:j + 1])
           i = j + 1
           continue
       i += 1
       continue
     code = ord(ch)
     if code < 32 or 0x7F <= code <= 0x9F or code == 0x200B:
       i += 1
       continue
     out.append(ch)
     i += 1
   return "".join(out)
 # Local pattern cache: the wrapper is copied into several module namespaces,
 # so it builds its own regex on first use instead of relying on a global.
 def _wrap_ansi_re():
   pat = _wrap_ansi_re.__dict__.get("pat")
   if pat is None:
     pat = re.compile(chr(27) + chr(92) + "[" + "[0-9;?]*[ -/]*[@-~]")
     _wrap_ansi_re.__dict__["pat"] = pat
   return pat
 def _last_wrap_point(text: str, width: int) -> int:
   """Index just past the last space that still fits in ``width`` cells (0 = none).

   ANSI escapes take no columns, so a coloured line breaks where a plain one
   would.  The live stream uses it to hand the terminal whole lines only.
   """
   if width <= 0:
     return 0
   cells = 0
   last_space = -1
   i = 0
   n = len(text)
   while i < n:
     ch = text[i]
     if ch == chr(27):
       j = i + 1
       if j < n and text[j] == "[":
         j += 1
         while j < n and (text[j].isdigit() or text[j] == ";"):
           j += 1
         if j < n and text[j] == "m":
           i = j + 1
           continue
       i += 1
       continue
     w = _char_width(ch)
     if cells + w > width:
       return last_space + 1 if last_space >= 0 else 0
     cells += w
     if ch == " " and cells < width:
       last_space = i
     i += 1
   return last_space + 1 if last_space >= 0 else 0
 def _wrap_ansi_line(line: str, width: int) -> List[str]:
   """Wrap one physical line at ``width`` columns, keeping ANSI colouring.

   Self-contained on purpose: it is copied into several module namespaces, so it
   parses escape sequences by hand instead of depending on a module-level regex.
   Breaks on spaces when possible and counts emoji / CJK as two cells.
   """
   if width <= 0:
     return [line]
   if _display_width(line) <= width:
     return [line]
   rows: List[str] = []
   cur: List[str] = []
   cur_w = 0
   last_space = -1
   i, n = 0, len(line)
   while i < n:
     ch = line[i]
     if ch == chr(27):
       j = i + 1
       if j < n and line[j] == "[":
         j += 1
         while j < n and not ("@" <= line[j] <= "~"):
           j += 1
         j += 1
       cur.append(line[i:j])
       i = j
       continue
     w = _char_width(ch)
     if cur_w + w > width and cur:
       # Slice the CHARACTER LIST, not the joined text: escape sequences are
       # single elements here, so string offsets would cut them in half.
       if last_space > 0 and last_space < len(cur):
         head = "".join(cur[:last_space]).rstrip()
         tail = "".join(cur[last_space + 1:])
         if head:
           rows.append(head)
         cur = [tail] if tail else []
         cur_w = _display_width(tail)
         last_space = -1
         if not tail:
           cur_w = 0
       else:
         rows.append("".join(cur))
         cur, cur_w, last_space = [], 0, -1
       continue
     cur.append(ch)
     cur_w += w
     if ch in (" ", "	"):
       last_space = len(cur) - 1
     i += 1
   if cur:
     rows.append("".join(cur))
   if not rows:
     rows.append("")
   return rows
 def _wrap_block(text: str, width: int) -> str:
   """Wrap a multi-line block (answer, panel body, table) to the terminal width."""
   if width <= 0:
     return text
   out: List[str] = []
   for line in str(text).split("\n"):
     out.extend(_wrap_ansi_line(line, width))
   return "\n".join(out)
 class TerminalView:
   def __init__(self, is_tty: bool) -> None:
     self.is_tty = is_tty
     win_vt = enable_windows_ansi() if (is_tty and os.name == "nt") else False
     if os.name == "nt":
       self.ansi = bool(is_tty and win_vt and os.environ.get("WT_SESSION"))
       self.color = bool(is_tty and win_vt and not os.environ.get("NO_COLOR"))
     else:
       posix_term_ok = os.environ.get("TERM", "xterm") != "dumb"
       self.ansi = bool(is_tty and posix_term_ok)
       self.color = bool(self.ansi and not os.environ.get("NO_COLOR"))
     self.lock = threading.RLock()
     self._footer: Optional[Callable[[], str]] = None
     self._compact_footer: Optional[Callable[[int], str]] = None
     self._footer_active = False
     self._rows = 0
     self._last_footer = 0.0
     self._spin_event: Optional[threading.Event] = None
     self._spin_thread: Optional[threading.Thread] = None
     self._typing_cond = threading.Condition()
     self._typing_queue: Deque[Tuple[str, Optional[str]]] = collections.deque()
     self._typing_chars = 0
     self._typing_thread: Optional[threading.Thread] = None
     self._typing_done = False
     self._typing_fast = False
     self._typing_abort = False
     self._typing_emitted = 0
   def _write(self, text: str) -> None:
     with self.lock:
       try:
         sys.stdout.write(text)
         sys.stdout.flush()
       except (BrokenPipeError, OSError, ValueError):
         # stdout gone (closed pipe / killed terminal): never crash the agent.
         pass
   def _safe_print(self, text: str = "") -> None:
     """One sanitised, wrapped, flushed write -- safe from any thread."""
     try:
       _, cols = self._size()
     except Exception:
       cols = 80
     safe = _wrap_block(_sanitize_stream_chunk(text), max(20, cols - 1))
     self._write(safe + "\n")
   def _size(self) -> Tuple[int, int]:
     size = shutil.get_terminal_size(fallback=(80, 24))
     return max(1, size.lines), max(1, size.columns)
   def start_footer(self, status: Callable[[], str], compact: Optional[Callable[[int], str]] = None) -> bool:
     self._footer = status
     self._compact_footer = compact
     rows, cols = self._size()
     # A full-screen footer on a phone eats half the message: mobile mode, or any
     # terminal narrower than a phone in landscape, keeps it off.
     if _DM_MOBILE_MODE or not self.ansi or rows < 8 or cols < 46:
       return False
     with self.lock:
       self._rows = rows
       self._footer_active = True
       sys.stdout.write(f"\x1b[1;{rows-1}r\x1b[{rows-1};1H")
       self._draw_footer_locked(force=True)
       sys.stdout.flush()
     return True
   def _draw_footer_locked(self, force: bool = False) -> None:
     if self._footer is None or not self.ansi:
       return
     rows, cols = self._size()
     if rows < 8 or cols < 30:
       if self._footer_active:
         sys.stdout.write("\x1b7\x1b[r\x1b8")
         self._footer_active = False
       return
     if not self._footer_active:
       self._rows = rows
       self._footer_active = True
       force = True
       sys.stdout.write(f"\x1b7\x1b[1;{rows-1}r\x1b8")
     now = time.monotonic()
     if not force and now - self._last_footer < 0.20:
       return
     if rows != self._rows:
       self._rows = rows
       sys.stdout.write(f"\x1b7\x1b[1;{rows-1}r\x1b8")
     try:
       line = str(self._footer())
       if self._compact_footer and len(line) > cols - 1:
         line = str(self._compact_footer(cols - 1))
     except Exception:
       line = "DocMind"
     line = re.sub(r"[\x00-\x1f\x7f-\x9f]", " ", line)
     line = _terminal_width(line, max(1, cols - 1))
     sys.stdout.write(f"\x1b7\x1b[{rows};1H\x1b[2K\x1b[2m{line}\x1b[0m\x1b8")
     self._last_footer = now
   def update_footer(self, force: bool = False) -> None:
     with self.lock:
       self._draw_footer_locked(force)
       if self.ansi:
         sys.stdout.flush()
   def stop_footer(self) -> None:
     with self.lock:
       if self._footer_active:
         rows, _ = self._size()
         sys.stdout.write(f"\x1b7\x1b[{rows};1H\x1b[2K\x1b[r\x1b8\n")
         sys.stdout.flush()
         self._footer_active = False
   @property
   def footer_active(self) -> bool:
     return self._footer_active
   def start_spinner(self, message: str) -> None:
     self.stop_spinner()
     if not self.is_tty:
       return
     if not self.ansi:
       self._write("… " + message + "\n")
       return
     event = threading.Event()
     self._spin_event = event
     def animate() -> None:
       frames = "⠋⠙⠹⠸⠼⠴⠦⠧⠇⠏"
       idx = 0
       while not event.is_set():
         with self.lock:
           _, cols = self._size()
           label = _terminal_width(frames[idx % len(frames)] + " " + message.replace("\n", " "), max(1, cols - 1))
           if self.color:
             label = "\x1b[36m" + label + "\x1b[0m"
           sys.stdout.write("\r\x1b[2K" + label)
           self._draw_footer_locked()
           sys.stdout.flush()
         idx += 1
         event.wait(0.10)
     self._spin_thread = threading.Thread(target=animate, name="DocMind spinner", daemon=True)
     self._spin_thread.start()
   def stop_spinner(self) -> None:
     event, thread = self._spin_event, self._spin_thread
     self._spin_event = None
     self._spin_thread = None
     if event:
       event.set()
     if thread and thread is not threading.current_thread():
       thread.join(timeout=1)
     if thread and self.ansi:
       self._write("\r\x1b[2K")
   def start_typing(self) -> None:
     self.stop_spinner()
     if self._typing_thread:
       self.finish_typing(True)
     with self._typing_cond:
       self._typing_queue.clear()
       self._typing_chars = 0
       self._typing_done = False
       self._typing_fast = False
       self._typing_abort = False
       self._typing_emitted = 0
       self._typing_tail = ""
       self._typing_tail_newline = False
     prompt = "\x1b[1;36mDocMind\x1b[0m: " if self.color else "DocMind: "
     try:
       _, cols = self._size()
     except Exception:
       cols = 80
     if cols >= 30:
       prompt = "\n".join(_wrap_ansi_line(prompt, max(20, cols - 1))) + " "
     # The stream shares this physical line, so it must know how much of it is
     # already used -- otherwise the first answer line overflows the terminal.
     self._stream_prompt_cols = _display_width(prompt.split("\n")[-1])
     self._write("\n" + prompt)
     def animate() -> None:
       while True:
         # One owner for the deque: the API thread only appends under the cond,
         # the animator pops under the cond AND the terminal lock.
         with self._typing_cond, self.lock:
           while not self._typing_queue and not self._typing_done and not self._typing_abort:
             self._typing_cond.wait(0.20)
             if not self._typing_queue and not self._typing_done:
               self.update_footer()
           if self._typing_abort:
             return
           if not self._typing_queue and self._typing_done:
             return
           pending = self._typing_chars
           emitted = self._typing_emitted
           width = 5 if emitted < 240 else (18 if emitted < 1200 else 50)
           if pending > 2500:
             width = max(width, 140)
           if pending > 12000:
             width = max(width, 600)
           if self._typing_fast:
             width = max(width, pending)
           pieces = []
           remaining = width
           while self._typing_queue and remaining > 0:
             part, style = self._typing_queue.popleft()
             take = part[:remaining]
             rest = part[remaining:]
             pieces.append((take, style))
             self._typing_chars -= len(take)
             remaining -= len(take)
             if rest:
               self._typing_queue.appendleft((rest, style))
           emitted_now = sum(len(part) for part, _ in pieces)
           self._typing_emitted += emitted_now
           fast = self._typing_fast
           if pieces:
             for part, style in pieces:
               try:
                 if self.color and style:
                   sys.stdout.write("\x1b[" + style + "m" + part + "\x1b[0m")
                 else:
                   sys.stdout.write(part)
               except (BrokenPipeError, OSError, ValueError):
                 self._typing_abort = True
                 return
             self._typing_tail = "".join(part for part, _ in pieces)[-1:]
             self._typing_tail_newline = self._typing_tail == "\n"
             self._draw_footer_locked()
             try:
               sys.stdout.flush()
             except (BrokenPipeError, OSError, ValueError):
               self._typing_abort = True
               return
         if not fast:
           time.sleep(0.018)
     self._typing_thread = threading.Thread(target=animate, name="DocMind typing", daemon=True)
     self._typing_thread.start()
   def append_typing(self, text: str, style: Optional[str] = None) -> None:
     """Queue streamed text. Only the animator thread touches the deque."""
     chunk = _sanitize_stream_chunk(text)
     if not chunk:
       return
     with self._typing_cond:
       self._typing_queue.append((chunk, style))
       self._typing_chars += len(chunk)
       self._typing_cond.notify()
   def finish_typing(self, fast: bool = False) -> None:
     thread = self._typing_thread
     if not thread:
       # Nothing is streaming, but the caret may still sit mid-line after an
       # aborted answer; a newline keeps the next message from being glued on.
       return
     with self._typing_cond:
       self._typing_fast = fast
       self._typing_done = True
       self._typing_cond.notify_all()
     try:
       while thread.is_alive():
         thread.join(0.10)
     except KeyboardInterrupt:
       with self._typing_cond:
         self._typing_abort = True
         self._typing_cond.notify_all()
       thread.join(0.5)
       self._typing_thread = None
       self._write("\n")
       raise
     self._typing_thread = None
     # Guarantee the stream ended on its own line, whatever happened above.
     if self._typing_emitted and not self._typing_ended_on_newline():
       self._write("\n")
     self._write("\n")
     self.update_footer(force=True)
   def _typing_ended_on_newline(self) -> bool:
     """True when the last characters written were a newline (best effort)."""
     try:
       return bool(getattr(self, "_typing_tail_newline", False))
     except Exception:
       return False
   @contextmanager
   def spinner(self, message: str):
     self.start_spinner(message)
     try:
       yield
     finally:
       self.stop_spinner()
 return locals()
