 def _should_expose_tools(user_input: str, messages: List[Dict[str, Any]]) -> bool:
  """Only suppress tools on unmistakable greetings / small talk; keep tools available for all real tasks!"""
  raw = (user_input or "").strip()
  if not raw:
    return False
  folded = _ascii_fold(raw)
  norm = re.sub(r"[^\w\s]+", " ", folded, flags=re.UNICODE)
  norm = re.sub(r"\s+", " ", norm).strip()
  if norm in _PURE_CHAT_EXACT:
    return False
  if _ACTION_CUES_ASCII_RE.search(folded):
    return True
  recent_msgs = messages[-4:] if len(messages) >= 4 else messages
  for m in recent_msgs:
    if m.get("role") == "tool" or m.get("tool_calls"):
      return True
    if m.get("role") == "assistant" and "?" in str(m.get("content") or ""):
      return True
  if re.fullmatch(r"[0-9\s+\-*/()%.,=^?]+(?:kac|eder|yapiyor|yapar|equals|what is)?[0-9\s?]*", folded):
    return False
  if len(norm.split()) <= 4 and _PURE_CONCEPT_QUESTION_RE.search(norm):
    return False
  if len(norm.split()) <= 3:
    return False
  return True
 def _is_explain_or_execute_candidate(user_input: str) -> bool:
  """
  Detect requests involving terminal/command/code execution or printing in terminal
  where the agent should ask the user: [1] Explain how to do it vs [2] Run it myself!
  """
  raw = (user_input or "").strip()
  if not raw or raw.startswith("/"):
    return False
  folded = _ascii_fold(raw)
  norm = re.sub(r"[^\w\s]+", " ", folded, flags=re.UNICODE)
  norm = re.sub(r"\s+", " ", norm).strip()
  if norm in _PURE_CHAT_EXACT or _PURE_CONCEPT_QUESTION_RE.search(norm):
    return False
  # Pure file read/summarize without terminal/execution cues should directly read the file
  file_read_only = bool(re.search(r"\b(?:ozetle|oku\b|icerigini|read\b|summarize)\b", folded)) and not bool(
    re.search(r"\b(?:terminal|calistir|kostur|yazdir|print|echo|bash|powershell|cmd)\b", folded)
  )
  if file_read_only:
    return False
  return bool(_TERMINAL_CANDIDATE_RE.search(folded))
 def _tool_fingerprint(name: str, arguments: Any) -> str:
  try:
    encoded = json.dumps([name, arguments], ensure_ascii=False, sort_keys=True, separators=(',', ':'), default=str)
  except (TypeError, ValueError):
    encoded = repr((name, arguments))
  return hashlib.sha256(encoded.encode('utf-8', errors='replace')).hexdigest()
 class DocMindAgent:
  def __init__(
    self,
    config_mgr: ConfigManager,
    ui: ConsoleUI,
    non_interactive: bool = False,
  ) -> None:
    self.config_mgr = config_mgr
    self.ui = ui
    self.non_interactive = non_interactive
    self.perm_mgr = PermissionManager(config_mgr, ui, non_interactive=non_interactive)
    self.undo_mgr = UndoManager()
    self.tools = ToolRegistry(config_mgr, ui, self.perm_mgr, self.undo_mgr)
    self.context = ConversationContext()
    self.history = ConversationHistory(config_mgr.home_dir, self._history_error, self._history_fork)
    self.context.on_append = self.history.append
    self.usage = UsageTracker()
    self.wizard = SetupWizard(config_mgr, ui, on_usage=self.record_verification_usage,
                 on_unknown_usage=self.usage.mark_interrupted)
    self._streamed_text = False
    self._streamed_chunks: List[str] = []
    self._turn_system_prompt: Optional[str] = None
    # v1.3 Squad Engine state
    self.squad_feed: Optional[Any] = None
    self._squad_request: str = ""
    self._squad_depth: int = 0
    self._squad_request: str = ""
    self._squad_depth: int = 0
    self._squad_tool_filter: Optional[Set[str]] = None
    # v1.3: a team run owns the outer turn, so the lead review closes it itself.
    self._squad_busy: bool = False
    self._squad_lock: Optional[Dict[str, Any]] = None
    self._turn_exec_mode: str = "auto"
    self.refresh_client()
  def _history_error(self, exc: Exception) -> None:
    self.config_mgr.log_error("history.write", repr(exc))
    self.ui.warn(t("history_write_error"))
  def _history_fork(self) -> None:
    self.ui.warn(t("history_forked"))
  def record_verification_usage(self, resp: ModelResponse, provider: Optional[str] = None,
                 model: Optional[str] = None) -> None:
    self.context.record_usage(resp.input_tokens, resp.output_tokens, update_context=False)
    self.usage.record(provider or self.config_mgr.config.provider, model or self.config_mgr.config.model,
             resp.input_tokens, resp.output_tokens, resp.reported_cost_usd, resp.usage_complete)
    refresh = getattr(self.ui, "refresh_footer", None)
    if refresh:refresh()
  def _stream_is_mine(self) -> bool:
    """True when the streaming callback belongs to the thread running now."""
    owner = getattr(getattr(self, "_stream_owner", None), "agent", None)
    return True if owner is None else owner is threading.current_thread()
  def _receive_stream_text(self, text: str) -> None:
    if not self._stream_is_mine():
      # A sub-agent's tokens must never land in the main console stream.
      self._streamed_text = True
      self.usage.live_chars += len(text)
      return
    self._streamed_text = self._streamed_text or bool(text)
    self._streamed_chunks.append(text)
    self.usage.live_chars += len(text)
    callback = getattr(self.ui, "stream_assistant_text", None)
    if callback:
      callback(text)
  def _finish_streamed_message(self, fast: bool = False) -> None:
    if self._streamed_text:
      callback = getattr(self.ui, "finish_streamed_message", None)
      if callback and self._stream_is_mine():
        try:
          callback(fast=fast)
        except TypeError:
          callback()
  def status_text(self, width: Optional[int] = None) -> str:
    cfg = self.config_mgr.config
    stats = self.usage.summary(cfg)
    total = f"{self.context.total_tokens:,}"
    if stats['missing_tokens']:
      total += " (" + t("footer_incomplete") + ")"
    if stats['live_tokens']:
      total += " +~" + f"{stats['live_tokens']:,}"
    limit, verified = context_limit_for(cfg)
    estimated = self.context.current_context_estimate()
    estimated += stats['live_tokens']
    pct = (estimated / max(limit, 1)) * 100.0
    limit_label = f"{limit:,}" + ("?" if not verified else "")
    if stats['missing_cost'] and not stats['known_cost_calls']:
      cost = t("footer_unknown")
    else:
      amount = stats['cost']
      decimals = 6 if amount < .01 else (4 if amount < 1 else 2)
      cost = "~$" + f"{amount:.{decimals}f}"
      if stats['missing_cost']:
        cost += " (" + t("footer_incomplete") + ")"
      elif stats['live_tokens']:
        cost += " (" + t("footer_calculating") + ")"
    full = (f"{t('footer_token')}: {total}  |  {t('footer_context')}: ~{estimated:,}/{limit_label} ({pct:.1f}%)"
        f"  |  {t('footer_cost')}: {cost}")
    if width is None or len(full) <= width:
      return full
    number = self.context.total_tokens + stats['live_tokens']
    if number >= 1_000_000_000:
      short_num = f"{number/1_000_000_000:.1f}B"
    elif number >= 1_000_000:
      short_num = f"{number/1_000_000:.1f}M"
    elif number >= 10_000:
      short_num = f"{number/1_000:.1f}k"
    else:
      short_num = f"{number:,}"
    if stats['live_tokens']:
      short_num = "~" + short_num
    if stats['missing_tokens']:
      short_num += "*"
    if stats['missing_cost'] and not stats['known_cost_calls']:
      short_cost = t("footer_unknown")
    else:
      short_cost = "~$" + f"{stats['cost']:.3g}"
      if stats['missing_cost']:
        short_cost += " (" + t("footer_incomplete") + ")"
      elif stats['live_tokens']:
        short_cost += " (" + t("footer_calculating") + ")"
    percent = f"{pct:.1f}" if pct < 1000 else ">999"
    compact = f"T:{short_num} C:{percent}% {short_cost}"
    if len(compact) > width:
      percent = f"{pct:.0f}" if pct < 1000 else ">999"
      short_cost = t("footer_unknown") if stats['missing_cost'] and not stats['known_cost_calls'] else (
        "~$" + f"{stats['cost']:.2g}" + ("*" if stats['missing_cost'] or stats['live_tokens'] else ""))
      compact = f"T:{short_num} C:{percent}% {short_cost}"
    return compact
  def refresh_client(self) -> None:
    supports_stream = bool(getattr(self.ui, "is_tty", False) and
               callable(getattr(self.ui, "stream_assistant_text", None)) and
               not self.non_interactive)
    def retry_notice(key, **values):
      self.usage.mark_interrupted()
      self.ui.warn(t(key, **values))
    self._stream_owner = threading.local()
    self.client = ProviderClient(self.config_mgr.config, self._receive_stream_text if supports_stream else None,
                  on_effort_fallback=lambda: retry_notice("effort_fallback"))
    self.client.on_compat_fallback = lambda: retry_notice("compat_fallback")
    self.client.on_budget_fallback = lambda limit: retry_notice("budget_fallback", limit=limit)
    self.client.on_probe_retry = lambda: retry_notice("probe_retry")
    self.client.on_connection_retry = lambda attempt, delay: retry_notice(
      "probe_transient_retry", attempt=attempt, seconds=int(delay + 0.999))
    self.client.on_probe_interrupted = self.usage.mark_interrupted
    self.client.on_thinking_rebase = lambda: self.ui.info(t("thinking_rebase"))
    self.client.on_vision_fallback = lambda: self.ui.warn(t("img_vision_fallback", model=self.config_mgr.config.model))
    self.client.on_vision_bridge = lambda bm: self.ui.info(t("vision_bridge_used", bridge_model=bm))
  # ---------------------------------------------------------------- v1.3 Squad
  def plan_with_model(self, prompt: str) -> str:
    """One-shot planner call used by the squad engine (no tools, no context)."""
    resp = self.client.generate(
      system_prompt="You are DocMind's planning module. Reply with JSON only.",
      messages=[{"role": "user", "content": prompt}],
      tools=[],
      timeout=120.0,
    )
    return str(getattr(resp, "text", "") or "")

  def _squad_should_offer(self, user_input: str) -> bool:
    cfg = self.config_mgr.config
    mode = str(getattr(cfg, "squad_mode", "ask") or "ask").lower()
    if mode == "off" or self._squad_depth > 0 or self.non_interactive:
      return False
    if getattr(self, "_squad_busy", False):
      return False
    if str(getattr(cfg, "reasoning_effort", "")).lower() == "aggressive":
      return False
    text = str(user_input or "").strip()
    if len(text) < 24:
      return False
    markers = ("website", "site", "app", "uygulama", "proje", "project", "game", "oyun",
               "api", "backend", "frontend", "dashboard", "bot", "sistem", "system",
               "refactor", "migrate", "automation", "otomasyon", "cli", "tool")
    lowered = text.lower()
    return any(m in lowered for m in markers) or len(text) > 160

  def _squad_offer_choice(self, user_input: str) -> str:
    """Ask once, in the interface language only (never two languages at a time)."""
    cfg = self.config_mgr.config
    if str(getattr(cfg, "squad_mode", "ask")).lower() == "auto":
      return "team"
    question = "\n".join([t("squad_choice_title"),
                          t("squad_choice_opt_team"),
                          t("squad_choice_opt_single")])
    options = [t("squad_choice_team"), t("squad_choice_single")]
    try:
      picked = self.ui.prompt_user_choice(question, options, 2)
    except Exception:
      return "single"
    picked_txt = str(picked).strip().lower()
    if picked_txt in ("1", "team"):
      return "team"
    if picked_txt in ("2", "single"):
      return "single"
    if picked_txt == options[0].strip().lower():
      return "team"
    if picked_txt == options[1].strip().lower():
      return "single"
    team_words = {"team", "ekip", "takim", "takım", "ajanlar", "parcala", "parçala",
                  "split", "equipo", "équipe", "mannschaft", "команда", "командою"}
    return "team" if picked_txt in team_words else "single"

  def run_squad(self, user_request: str, lead_note: str = "") -> Dict[str, Any]:
    """v1.3: plan -> named agents (parallel) -> live feed -> lead review."""
    cfg = self.config_mgr.config
    self.squad_feed = SquadFeed(mode="full")
    self._squad_request = user_request
    self._squad_depth += 1
    prev_busy = getattr(self, "_squad_busy", False)
    self._squad_busy = True
    try:
      outcome = squad_run(
        self, user_request,
        max_agents=max(2, min(8, int(getattr(cfg, "squad_max_agents", 6) or 6))),
        feed=self.squad_feed,
        parallel=bool(getattr(cfg, "squad_parallel", True)),
        lead_note=lead_note,
      )
    finally:
      self._squad_depth -= 1
      self._squad_busy = prev_busy
    if outcome.get("ok"):
      self.ui.print_panel("SQUAD SUMMARY",
                          squad_dashboard(self.squad_feed, user_request, "squad"),
                          style="bright_cyan")
      log = self.squad_feed.write_log(Path(self.tools.cwd))
      if log:
        self.ui.info("squad log: " + str(log))
    return outcome

  def run_squad_review(self, user_request: str) -> bool:
    """The lead's own final pass: join the pieces, verify them, then report."""
    if not self.squad_feed:
      return False
    self.ui.print_panel("SQUAD REVIEW", t("squad_review_start"), style="bright_blue")
    self._squad_depth += 1
    prev_busy = getattr(self, "_squad_busy", False)
    self._squad_busy = True
    try:
      return bool(self.run_turn(squad_review_prompt(user_request, self.squad_feed), review=True))
    finally:
      self._squad_depth -= 1
      self._squad_busy = prev_busy

  @staticmethod
  def _squad_worker_copy(parent: Any) -> Any:
    """Shallow copy of the agent for ONE sub-agent: own context and counters."""
    import copy as _copy
    worker = _copy.copy(parent)
    worker.context = ConversationContext()
    worker.non_interactive = True
    worker._streamed_text = False
    worker._streamed_chunks = []
    worker._stream_owner = threading.local()
    worker._turn_system_prompt = None
    worker._turn_exec_mode = "auto"
    worker._squad_depth = max(1, int(getattr(parent, "_squad_depth", 0) or 0))
    worker._squad_busy = True
    worker._squad_tool_filter = None
    # Sub-agents never stop to ask a question (they run beside each other);
    # the lead reviews and verifies every change afterwards.
    worker.perm_mgr = PermissionManager(parent.config_mgr, parent.ui, non_interactive=True)
    worker.tools = _copy.copy(parent.tools)
    worker.tools.perm_mgr = worker.perm_mgr
    return worker

  def squad_bind_lock(self, deps: Optional[Dict[str, Any]]) -> None:
    """Share the squad's claim/console state with the worker copies."""
    self._squad_lock = deps

  def run_child_turn(self, prompt: str, step: Optional[Dict[str, Any]] = None,
                     feed: Optional[Any] = None, max_rounds: int = 10) -> Dict[str, Any]:
    """Run ONE sub-agent step on its own worker copy (safe under threads)."""
    step = step or {}
    feed = feed or self.squad_feed
    handle = str(step.get("handle") or "agent")
    allowed = {str(t).lower() for t in (step.get("tools") or [])}
    cap = max(3, min(int(max_rounds), 20))
    worker = self._squad_worker_copy(self)
    worker._squad_tool_filter = allowed or None
    worker.context.add_user(prompt)
    deps = getattr(self, "_squad_lock", None)
    if not isinstance(deps, dict):
      deps = {}
    console = deps.get("console") or threading.RLock()
    active = deps.get("active") if isinstance(deps.get("active"), dict) else None
    rounds = 0
    ok = False
    report = ""
    error = ""
    last_batch = None
    repeated_batches = 0
    if active is not None:
      active[handle] = True
    try:
      while rounds < cap:
        rounds += 1
        if feed:
          feed.thinking(handle, "")
        # No console lock around the API call: the model calls must overlap,
        # otherwise "parallel" would only mean "queued". Children print nothing
        # here (streaming is filtered by _stream_owner, no spinner for threads).
        resp = worker._generate_resilient()
        if resp is None:
          error = "model call failed"
          break
        if getattr(resp, "text", ""):
          report = str(resp.text)[:400]
        if not getattr(resp, "tool_calls", None):
          ok = True
          break
        for tc in resp.tool_calls:
          if feed:
            feed.doing(handle, tc.name, str((tc.arguments or {}).get("path") or "")[:60])
          worker._run_squad_tool(handle, tc)
        # An agent that only repeats the same tool call is stuck, not working.
        fingerprints = [hashlib.sha1((str(tc.name) + repr(sorted((tc.arguments or {}).items()))).encode("utf-8", "replace")).hexdigest()
                        for tc in resp.tool_calls]
        if last_batch and fingerprints == last_batch:
          repeated_batches += 1
        else:
          repeated_batches = 0
        last_batch = fingerprints
        if repeated_batches >= 1:
          ok = True
          report = report or "same tool call repeated; step closed"
          break
    except Exception as exc:
      error = "%s: %s" % (type(exc).__name__, exc)
    finally:
      if active is not None:
        active.pop(handle, None)
      if isinstance(step.get("files"), list):
        for owned in step["files"]:
          worker._squad_release(handle, {"path": owned})
    return {"ok": ok, "rounds": rounds, "report": report.strip(), "error": error,
            "steps": rounds}

  @staticmethod
  def _squad_file_key(path: Any) -> str:
    """Normalise a path so two agents touching 'app.py' really collide."""
    try:
      clean = str(path).replace("\\", "/").strip()
      while clean.startswith("./"):
        clean = clean[2:]
      return clean.lower() or str(path)
    except Exception:
      return str(path)

  def _squad_claim(self, handle: str, tool_name: str, args: Any) -> str:
    """Before a writing call: never touch a file another agent is editing.

    Independent agents really run at the same time; only a genuinely shared file
    waits, and it waits with a clear note instead of overwriting someone's work.
    """
    if not isinstance(args, dict) or not handle:
      return ""
    deps = getattr(self, "_squad_lock", None)
    if not isinstance(deps, dict):
      return ""
    owners, lock = deps.get("owners"), deps.get("busy")
    if not isinstance(owners, dict) or lock is None:
      return ""
    me = str(handle)
    paths = [args.get(k) for k in ("path", "target", "source", "destination", "archive_path")
             if args.get(k)]
    for raw in paths:
      key = self._squad_file_key(raw)
      with lock:
        holder = owners.get(key)
        if holder and holder != me:
          return ("%s: `%s` is being edited by %s right now; left it alone. Finish the "
                  "rest of your step and report this file as deferred." % (me, raw, holder))
        owners[key] = me
    return ""

  def _squad_release(self, handle: str, args: Any) -> None:
    """After a writing call: hand the file back so the next agent may use it."""
    if not isinstance(args, dict) or not handle:
      return
    deps = getattr(self, "_squad_lock", None)
    if not isinstance(deps, dict):
      return
    owners, lock = deps.get("owners"), deps.get("busy")
    if not isinstance(owners, dict) or lock is None:
      return
    me = str(handle)
    with lock:
      for k in ("path", "target", "source", "destination", "archive_path"):
        if args.get(k):
          fk = self._squad_file_key(args.get(k))
          if owners.get(fk) == me:
            owners.pop(fk, None)

  def _run_squad_tool(self, handle: str, tc: Any) -> None:
    """Execute one tool call for a sub-agent, respecting its tool whitelist."""
    name = str(getattr(tc, "name", ""))
    if (self._squad_tool_filter and name.lower() not in self._squad_tool_filter
        and name.lower() not in ("aggressive_audit", "check_syntax")):
      self.ui.warn("%s: tool '%s' is not in this agent's whitelist; skipped." % (handle, name))
      return
    args = getattr(tc, "arguments", {}) or {}
    if not isinstance(args, dict):
      args = {}
    writing = name in ("write_file", "edit_file", "multi_edit", "delete_path",
                       "move_or_copy", "archive_tool")
    if writing:
      conflict = self._squad_claim(handle, name, args)
      if conflict:
        self.ui.warn(conflict)
        return
    deps = getattr(self, "_squad_lock", None)
    console = deps.get("console") if isinstance(deps, dict) else None
    try:
      if console is not None:
        # One tool call at a time on the shared console: no mixed diff boxes.
        with console:
          self.tools.execute(name, args)
      else:
        self.tools.execute(name, args)
    except Exception as exc:
      self.ui.warn("%s: %s failed: %s" % (handle, name, exc))
    finally:
      if writing:
        self._squad_release(handle, args)

  def _aggressive_final_gate(self, touched: Optional[Set[str]] = None,
                             rounds: int = 0) -> str:
    """Aggressive mode: audit the folder before a turn is allowed to end.

    Only *blocking* problems force another round: syntax errors anywhere, or findings
    inside files this turn touched. Pre-existing markers elsewhere are reported once
    and never trap the turn in a loop.
    """
    cwd = Path(self.tools.cwd)
    self.ui.info(t("aggressive_audit_running"))
    try:
      from docmind.tools.project import aggressive_audit_folder as _ag_audit
      clean, detail, scanned = _ag_audit(cwd, touched=touched)
    except Exception as exc:
      self.ui.warn(f"Aggressive audit unavailable: {exc}")
      return "done"
    if clean:
      self.ui.success(t("aggressive_audit_clean", files=scanned))
      return "done"
    blocking: List[str] = []
    if "BLOCKING:" in detail:
      blocking = [ln.strip() for ln in detail.split("BLOCKING:", 1)[1].splitlines() if ln.strip().startswith("- ")]
    advisory = [ln.strip() for ln in detail.splitlines()
                if ln.strip().startswith("- ") and ln.strip() not in blocking]
    if advisory:
      self.ui.warn(t("aggressive_audit_issues", count=len(advisory)))
      for line in advisory[:8]:
        print("   " + line)
      self.ui.info(t("aggressive_audit_advisory"))
    if not blocking:
      return "done"
    self.ui.warn(t("aggressive_audit_issues", count=len(blocking)))
    for line in blocking[:12]:
      print("   " + line)
    # Hard stops: never let the audit trap the conversation in a spiral.
    if rounds >= 3:
      self.ui.warn(t("aggressive_audit_gave_up", count=len(blocking)))
      for line in blocking[:6]:
        print("   " + line)
      self.ui.info(t("aggressive_audit_leftover"))
      return "done"
    fingerprint = "|".join(blocking)
    if rounds >= 1 and fingerprint == getattr(self, "_ag_gate_fingerprint", ""):
      self.ui.warn(t("aggressive_audit_stuck", count=len(blocking)))
      return "done"
    self._ag_gate_fingerprint = fingerprint
    remaining = max(0, 3 - rounds)
    self.context.add_user(
      "[AGGRESSIVE AUDIT] These problems must be fixed before this turn can end:\n"
      + "\n".join(blocking[:20])
      + f"\nFix them now (syntax errors, unfinished markers or error patterns in the files you just wrote), re-run "
        f"the relevant check, then report. Leave unrelated pre-existing findings alone. Attempts left: {remaining}."
    )
    return "continue"


